// --- HOW TO CAUSE A LEAK ---
const leakedArray = [];

function handleRequest(userObj) {
  // The intent was just to log it, but we accidentally save it to a global array permanently.
  leakedArray.push(userObj);
  console.log(`Processed user ${userObj.name}`);
}

// Simulate 10,000 requests over time
for(let i=0; i<10000; i++) {
  handleRequest({ name: "User" + i, data: new Array(1000).fill("Heavy Data") });
}

// The V8 Garbage Collector comes by. 
// It says: "Can I delete these user objects?"
// The system says: "NO! The global 'leakedArray' is still using them!"
// The RAM usage climbs and climbs until the server crashes.

console.log(`Leak size: ${leakedArray.length} items permanently stuck in RAM.`);
